        "7055" to "حضرت جنادہ بن ابی امیہ نے بیان کیا کہ ہم حضرت عبادہ بن صامت رضی اللہ عنہ کے پاس گئے جبکہ وہ بیمار تھے۔ ہم نے عرض کیا: اللہ آپ کو صحت دے، آپ ہمیں کوئی ایسی حدیث سنائیں جس سے اللہ تعالیٰ آپ کو نفع پہنچائے جو آپ نے نبی کریم صلی اللہ علیہ وسلم سے سنی ہو۔ انہوں نے کہا: نبی کریم صلی اللہ علیہ وسلم نے ہمیں بلایا تو ہم نے آپ کی بیعت کی، چنانچہ ان باتوں میں جو آپ نے ہم سے عہد لیا وہ یہ تھا کہ ہم خوشی اور ناگواری، تنگی اور آسانی میں، اور اس بات پر کہ ہم پر دوسروں کو ترجیح دی جائے، ہر حال میں امیر کی بات سنیں گے اور اطاعت کریں گے، اور اہل حکومت سے حکومت کے معاملے میں جھگڑا نہیں کریں گے، الا یہ کہ تم کھلا کفر دیکھو جس کے متعلق تمہارے پاس اللہ کی طرف سے کوئی واضح دلیل ہو۔",
        "7056" to "حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم پر لازم ہے کہ اپنے حکمران کی بات سنو اور اطاعت کرو، خواہ تنگی ہو یا آسانی، خوشی ہو یا ناگواری، اور اگرچہ تمہارا حق مارا جائے، اور حکمرانوں سے حکومت کے معاملے میں کشمکش نہ کرو سوائے اس کے کہ تم کھلا کفر دیکھو جس پر تمہارے پاس اللہ کی طرف سے روشن دلیل ہو۔"
    )

    private val nasaiSupplements: Map<String, String> = mapOf(
        "207" to "ام المؤمنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ام حبیبہ رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے خون (استحاضہ) کے متعلق دریافت کیا - عائشہ رضی اللہ عنہا نے فرمایا: میں نے ان کا طشت خون سے بھرا ہوا دیکھا - تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جتنے دن تمہارے حیض کے دن ہوتے تھے اتنے دن نماز سے رکی رہو، پھر غسل کر لیا کرو اور نماز پڑھو۔",
        "384.2" to "حضرت اعمش سے اسی اسناد کے ساتھ اسی مفہوم کی حدیث مروی ہے کہ حائضہ عورت کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کس طرح ازار کی حالت میں آرام فرماتے تھے۔"
    )

    private val malikSupplements: Map<String, String> = mapOf(
        "2" to "ام المؤمنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز پڑھتے تھے اور دھوپ حجرے کے اندر ہوتی تھی دیواروں پر چڑھنے سے پہلے۔",
        "631.5" to "امام مالک رحمہ اللہ نے فرمایا: زکوٰۃ کے احکام میں اعتدال اور فقراء و مساکین کے حق کی ادائیگی کا سختی سے اہتمام کیا جائے گا۔"
    )

    fun getTranslation(bookSlug: String, hadithNumber: String): String? {
        val normNum = HadithRepository.normalizeHadithNumber(hadithNumber)
        val slug = bookSlug.lowercase().trim()

        return when {
            slug.contains("bukhari") -> {
                bukhariSupplements[normNum] ?: bukhariSupplements[hadithNumber]
            }
            slug.contains("nasai") -> {
                nasaiSupplements[normNum] ?: nasaiSupplements[hadithNumber]
            }
            slug.contains("malik") || slug.contains("muwatta") -> {
                malikSupplements[normNum] ?: malikSupplements[hadithNumber]
            }
            slug.contains("nawawi") || slug.contains("arbaeen") -> {
                BuiltInHadithsProvider.getHadithsForBook("arbaeen-nawawi").firstOrNull { 
                    it.hadithNumber == normNum || it.hadithNumber == hadithNumber || HadithRepository.normalizeHadithNumber(it.hadithNumber) == normNum 
                }?.urduTranslation?.takeIf { it.isNotBlank() }
            }
            slug.contains("qudsi") -> {
                BuiltInHadithsProvider.getHadithsForBook("hadith-qudsi").firstOrNull { 
                    it.hadithNumber == normNum || it.hadithNumber == hadithNumber || HadithRepository.normalizeHadithNumber(it.hadithNumber) == normNum 
                }?.urduTranslation?.takeIf { it.isNotBlank() }
            }
            else -> null
        }
    }

    fun hasUrduScript(str: String): Boolean {
        if (str.isBlank()) return false
        return str.any { it in '\u0600'..'\u06FF' || it in '\u0750'..'\u077F' || it in '\u08A0'..'\u08FF' }
    }
}
